html=r'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>WellGuard AI | DATA TITANS | Synthetic Demo</title>
<style>
:root{--bg:#081321;--panel:#11243a;--panel2:#0d2034;--line:#2a4359;--text:#ebf6ff;--muted:#a2b5c8;--teal:#27d4c8;--gold:#ffbd64;--red:#fa7d88}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 Inter,system-ui,-apple-system,Segoe UI,Arial}header{border-bottom:1px solid var(--line);background:#0c1b2c;padding:18px 36px;display:flex;align-items:center;justify-content:space-between;gap:12px}.logo{font-weight:900;font-size:23px;letter-spacing:-.8px}.logo b{color:var(--teal)}.tiny{font-size:12px;color:var(--muted)}.pill{font-size:12px;font-weight:700;border:1px solid #3e6c70;border-radius:25px;color:#83ece4;background:#133535;padding:5px 12px}.shell{max-width:1500px;margin:auto;padding:27px 30px 80px}.eyebrow{color:var(--teal);font-size:12px;font-weight:800;letter-spacing:2px;text-transform:uppercase}.hero{margin:8px 0 10px;font-weight:900;font-size:43px;letter-spacing:-1.9px;line-height:1.1}.lead{color:var(--muted);font-size:16px;margin:0 0 20px}.warning{padding:14px 18px;border:1px solid #60522e;border-radius:13px;background:#272317;color:#e8d4ad;margin:16px 0 20px;font-size:13px}.nav{display:flex;gap:9px;flex-wrap:wrap;margin:20px 0 22px}.nav button{border:1px solid var(--line);background:var(--panel);color:var(--muted);padding:10px 18px;border-radius:10px;cursor:pointer;font-weight:700;font-size:14px}.nav button.active{border-color:var(--teal);color:#061321;background:var(--teal)}.tab{display:none}.tab.active{display:block}.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.kpi,.panel{background:var(--panel);border:1px solid var(--line);border-radius:15px;padding:20px}.kpi .n{font-size:32px;font-weight:800;letter-spacing:-1px;color:#f6fbff}.kpi .t{color:var(--muted);font-size:12px;margin-top:7px}.section{font-weight:800;font-size:20px;letter-spacing:-.5px;margin:28px 0 12px}.two{display:grid;grid-template-columns:1.3fr 1fr;gap:16px}.twoeq{display:grid;grid-template-columns:1fr 1fr;gap:16px}.panel h3{font-size:17px;letter-spacing:-.3px;margin:0 0 14px}.panel p{color:var(--muted);margin:10px 0}.stack{display:grid;gap:12px}.step{display:flex;gap:13px;align-items:flex-start}.step span{flex-shrink:0;width:30px;height:30px;border:1px solid var(--teal);color:var(--teal);border-radius:9px;text-align:center;padding:3px;font-weight:800}.chart{width:100%;height:330px}.controls{display:flex;gap:15px;flex-wrap:wrap;align-items:end;margin:18px 0}.control{display:flex;flex-direction:column;gap:6px;min-width:160px;flex:1}.control label{font-size:12px;font-weight:700;color:#c6d6e3}select,input{background:#0d1b2c;border:1px solid #42617a;color:var(--text);border-radius:8px;padding:10px;font-size:14px}input[type=range]{padding:0;accent-color:var(--teal)}.btn{border:0;color:#061321;background:var(--teal);padding:10px 14px;border-radius:10px;cursor:pointer;font-weight:800}.btn.alt{background:#243e55;color:#eaf7ff;border:1px solid #4a6e8a}table{border-collapse:collapse;width:100%;font-size:13px}th{text-align:left;color:#97b4c8;font-weight:700;background:#173047;padding:11px 13px}td{border-bottom:1px solid #274258;padding:11px 13px}tr:hover td{background:#24425b;cursor:pointer}.report{background:#0e2032;border-left:3px solid var(--teal);padding:17px 18px;border-radius:0 10px 10px 0;color:#c4d8e7;font-size:14px}.report strong{color:#eff9ff}.muted{color:var(--muted)}.yellow{color:var(--gold)}footer{margin:38px 0;color:#829fb7;font-size:12px;text-align:center}ul{padding-left:21px}li{margin:7px 0}a{color:#8aece6}.note{font-size:12px;color:#99b3c7}.spacer{height:4px}
@media(max-width:850px){.kpis{grid-template-columns:repeat(2,1fr)}.two,.twoeq{grid-template-columns:1fr}.hero{font-size:34px}header{padding:14px}.shell{padding:18px}}
</style>
<script>__PLOTLY_SOURCE__</script></head><body><header><div><div class="logo">◈ WellGuard <b>AI</b></div><div class="tiny">DATA TITANS • DSMLC Datathon 2026</div></div><div class="pill">SYNTHETIC WELL DATA • SAFE DEMONSTRATION</div></header><main class="shell"><div class="eyebrow">Operational intelligence | Historical research prototype</div><div class="hero">Predict. Prioritize. Explain.</div><p class="lead">Turn industrial well history into a reviewable, evidence-first inspection workflow.</p><div class="warning"><strong>Research guardrail.</strong> Private well identifiers, scores and trends are not distributed in this public demonstration. All visible well-level records are <strong>synthetic</strong>. The model performance statistics below are from a separately evaluated historical dataset. No demonstrated failure prevention or realized production savings.</div>
<div class="kpis"><div class="kpi"><div class="n">0.164</div><div class="t">Historic LightGBM average precision</div></div><div class="kpi"><div class="n">0.103</div><div class="t">Continuous failure-recency baseline AP</div></div><div class="kpi"><div class="n">0.805</div><div class="t">Historical test ROC-AUC</div></div><div class="kpi"><div class="n">116 / 643</div><div class="t">Eligible recorded events caught at 25 alerts/week</div></div></div>
<nav class="nav"><button class="active" data-tab="overview">Overview</button><button data-tab="queue">Inspection queue</button><button data-tab="investigator">Well investigator</button><button data-tab="impact">Impact simulator</button><button data-tab="method">Evidence & limitations</button></nav>
<section class="tab active" id="overview"><div class="two"><div class="panel"><h3>Historical observed downtime exposure</h3><div class="chart" id="downtimeChart"></div><p class="note">Recorded cause categories, estimated lost-oil totals. Historical context, not recoverable value or proven failure attribution.</p></div><div class="panel"><h3>Operational workflow</h3><div class="stack"><div class="step"><span>1</span><div><strong>Observe</strong><br><small class="muted">Historical production, pump signals and downtime.</small></div></div><div class="step"><span>2</span><div><strong>Rank</strong><br><small class="muted">Risk model scores eligible producing well-weeks.</small></div></div><div class="step"><span>3</span><div><strong>Investigate</strong><br><small class="muted">Operators review measurements, reporting gaps and past records.</small></div></div><div class="step"><span>4</span><div><strong>Decide and learn</strong><br><small class="muted">Field specialists choose actions; verified outcomes improve future evaluation.</small></div></div></div><div class="warning"><strong>Focus:</strong> better inspection targeting—not automated equipment controls.</div></div></div><h2 class="section">Validated ranking comparison</h2><div class="panel"><div id="modelChart" class="chart"></div><p class="note">Evaluation on later, observed well-weeks (June–October 2026). Prevalence: 4.5%. An algorithmic score is not a calibrated failure probability.</p></div></section>
<section class="tab" id="queue"><h2 class="section">Capacity-constrained inspection queue</h2><div class="controls"><div class="control"><label for="week">Historical Sunday snapshot</label><select id="week"></select></div><div class="control"><label for="capacity">Available inspection slots</label><select id="capacity"><option>10</option><option selected>25</option><option>50</option><option>100</option></select></div><div class="control"><label for="cooldown">Repeat review exclusion (exploratory)</label><select id="cooldown"><option value="0" selected>No cooldown</option><option value="1">Skip next week</option><option value="2">Skip next 2 weeks</option></select></div><div class="control"><label for="hindsight">Future labels</label><select id="hindsight"><option value="no">Hidden (operator view)</option><option value="yes">Shown (retrospective demo)</option></select></div><button class="btn" id="download">Download synthetic shortlist CSV</button></div><div class="twoeq"><div class="panel"><h3>Ranked synthetic wells (as-of only)</h3><p class="note">Cooldown uses earlier queue selections only; any retrospective improvement is exploratory and unvalidated.</p><div style="max-height:410px;overflow:auto"><table><thead><tr><th>Rank</th><th>Well</th><th>Score</th><th>Oil m³/day</th><th>Down fraction</th><th id="outcomeHead">Select</th></tr></thead><tbody id="queueRows"></tbody></table></div></div><div class="panel"><h3>Risk vs. production • illustrative</h3><div class="chart" id="scatterChart"></div><p class="note">Click a table row to inspect the fabricated well example; scores are NOT real company scores.</p></div></div></section>
<section class="tab" id="investigator"><h2 class="section">Evidence-first Well Investigator</h2><div class="controls"><div class="control"><label for="well">Synthetic example well</label><select id="well"></select></div><div class="control"><label for="wdate">Observation date</label><select id="wdate"></select></div><div class="pill">NO UNSUPPORTED ROOT-CAUSE CLAIMS</div></div><div class="twoeq"><div class="panel"><h3>Recent simulated alert score</h3><div class="chart" id="riskChart"></div></div><div class="panel"><h3>Recent simulated daily oil production</h3><div class="chart" id="oilChart"></div></div></div><h2 class="section">Evidence brief</h2><div class="report" id="investigatorText"></div></section>
<section class="tab" id="impact"><h2 class="section">Business sensitivity • assumptions, not savings</h2><p class="muted">An operator can test whether a prospective trial might justify inspection resources under explicit, hypothetical assumptions. None of the values below is inferred from the historical failure model.</p><div class="panel"><div class="controls"><div class="control"><label>Inspections/week <b id="vInspect"></b></label><input id="inspect" type="range" min="5" max="100" step="5" value="25"></div><div class="control"><label>Assumed candidate events/week <b id="vEvents"></b></label><input id="events" type="range" min="0" max="20" step="0.5" value="3"></div><div class="control"><label>Assumed avoidable oil/event (m³) <b id="vOil"></b></label><input id="oil" type="range" min="0" max="150" step="5" value="20"></div></div><div class="controls"><div class="control"><label>Assumed addressable fraction <b id="vAddr"></b></label><input id="address" type="range" min="0" max="100" step="5" value="25"></div><div class="control"><label>Assumed successful intervention fraction <b id="vSuccess"></b></label><input id="success" type="range" min="0" max="100" step="5" value="30"></div><div class="control"><label>Assumed realized CAD/m³ <b id="vValue"></b></label><input id="value" type="range" min="0" max="1200" step="25" value="400"></div><div class="control"><label>Assumed CAD/inspection <b id="vCost"></b></label><input id="cost" type="range" min="0" max="1000" step="25" value="50"></div></div><div class="report" id="breakEvenReport" role="status" style="margin:14px 0">Break-even scenario calculates when inputs change.</div><div class="kpis"><div class="kpi"><div class="n" id="simOil">—</div><div class="t">Hypothetical avoided volume (m³/week)</div></div><div class="kpi"><div class="n" id="simGross">—</div><div class="t">Hypothetical gross value/week</div></div><div class="kpi"><div class="n" id="simSpend">—</div><div class="t">Assumed inspection spending/week</div></div><div class="kpi"><div class="n" id="simNet">—</div><div class="t">Hypothetical net/week</div></div></div><div id="sensitivityChart" class="chart"></div><div class="warning">No claim of causal uplift, failure prevention, netback, actual inspection cost, or commercial ROI. A prospective trial must measure all of these.</div></div></section>
<section class="tab" id="method"><div class="twoeq"><div class="panel"><h3>Validation facts</h3><ul><li>Train: June 2025–March 1, 2026</li><li>Validation: March–May 2026, with horizon gap</li><li>Test: June–October 2026, with horizon gap</li><li>22,580 eligible well-week observations; 4.5% recorded-failure prevalence</li><li>Average precision 0.164, compared with 0.103 continuous failure-recency baseline</li><li>643 eligible distinct failure events: full model 116, operating-only model 111, continuous recency 75 at 25 alerts/week</li><li>With seven-day-old inputs the refit full model surfaced 66 versus 75 for lagged recency at 25 slots. Confirm data availability in a shadow trial.</li><li>Score is <strong>uncalibrated</strong>; no true cost-effective threshold established</li></ul></div><div class="panel"><h3>Material limitations</h3><ul><li>Failure reporting nearly absent before 2025</li><li>Failure and job entries frequently on the same date</li><li>High pump-sensor missingness; populations differ</li><li>Actual maintenance costs and actions largely unavailable</li><li>Well-week labels are not independent events</li><li>No prospective operation, counterfactual impact or causal diagnosis</li></ul></div></div><h2 class="section">Why this is a measured proposal</h2><div class="report">The public version uses **synthetic-only per-well records** for interactive demonstration. The proprietary original is excluded. To reproduce actual historical metrics, the registered team must run the provided scripts locally with the competition Parquet files and compare against the documented results. AI assistance is disclosed in the accompanying repository; every output requires human verification.</div></section>
<footer>DATA TITANS • WellGuard AI • educational historical decision-support prototype • synthetic per-well demo • 2026</footer></main>
<script>const DEMO=__DEMO_DATA__;const CATS=__CATEGORY_DATA__;const METRICS=__METRIC_DATA__;
const $=id=>document.getElementById(id);const money=x=>'CAD '+Number(x).toLocaleString('en-CA',{maximumFractionDigits:0});const plotCfg={displayModeBar:false,responsive:true};const theme={paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{color:'#bfd2e3',size:12},margin:{l:56,r:18,t:18,b:58},xaxis:{gridcolor:'#2b4257'},yaxis:{gridcolor:'#2b4257'}};
const WEEKS=[...new Set(DEMO.map(r=>r.week_end))];const WELLS=[...new Set(DEMO.map(r=>r.uwi))];
function showTab(id){document.querySelectorAll('.tab').forEach(e=>e.classList.toggle('active',e.id===id));document.querySelectorAll('.nav button').forEach(e=>e.classList.toggle('active',e.dataset.tab===id));setTimeout(()=>window.dispatchEvent(new Event('resize')),120)}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));
function initSelect(id,items,desc=false){const el=$(id);el.innerHTML=items.map(x=>`<option value="${x}">${x}</option>`).join('');if(desc)el.value=items[items.length-1]}
initSelect('week',WEEKS,true);initSelect('wdate',WEEKS,true);initSelect('well',WELLS);
function lineChart(id,x,y,color,title){Plotly.react(id,[{x,y,type:'scatter',mode:'lines+markers',line:{color,width:3},marker:{size:7}}],{...theme,height:310,title:{text:title,font:{size:13}},showlegend:false,yaxis:{type:'linear',tickformat:'.2f',gridcolor:'#2b4257'},xaxis:{type:'date',gridcolor:'#2b4257'}},plotCfg)}
function overview(){Plotly.react('downtimeChart',[{type:'bar',orientation:'h',x:CATS.map(c=>c[1]).reverse(),y:CATS.map(c=>c[0]).reverse(),marker:{color:'#25cfc2'}}],{...theme,height:345,margin:{l:192,r:20,t:15,b:50},xaxis:{title:'Estimated lost oil (m³)',gridcolor:'#2b4257'},yaxis:{gridcolor:'#2b4257'}},plotCfg);
Plotly.react('modelChart',[{type:'bar',orientation:'h',x:[.045,.046,.103,.148,.164],y:['Test prevalence','Recent downtime','Failure recency','Operating-data model','Full LightGBM'],marker:{color:['#4e657e','#63869f','#8799a8','#19a49c','#25cfc2']},text:['0.045','0.046','0.103','0.148','0.164'],textposition:'outside'}],{...theme,height:325,margin:{l:180,r:75,t:20,b:40},xaxis:{range:[0,.20],title:'Average precision',gridcolor:'#2b4257'}},plotCfg)}
function sortedWeek(w){return DEMO.filter(r=>r.week_end===w).sort((a,b)=>(b.relative_risk_score-a.relative_risk_score)||a.uwi.localeCompare(b.uwi))}
function scheduleDemo(){const n=Number($('capacity').value),cool=Number($('cooldown').value);const last={};const result={};WEEKS.forEach((w,i)=>{const choice=[];for(const r of sortedWeek(w)){if(last[r.uwi]!==undefined && i-last[r.uwi]<=cool)continue;choice.push(r);if(choice.length>=n)break;}choice.forEach(r=>{last[r.uwi]=i});result[w]=choice;});return result}
function weekItems(){return sortedWeek($('week').value)}
function queue(){const sorted=weekItems(),n=Number($('capacity').value),known=$('hindsight').value==='yes';const top=scheduleDemo()[$('week').value] || []; $('outcomeHead').textContent=known?'Recorded failure*':'Select';$('queueRows').innerHTML=top.map((r,i)=>`<tr data-well="${r.uwi}"><td>${i+1}</td><td>${r.uwi}</td><td>${r.relative_risk_score.toFixed(3)}</td><td>${r.oil_daily_avg_2w.toFixed(1)}</td><td>${r.down_fraction_2w.toFixed(2)}</td><td>${known?r.target_14d:'Inspect →'}</td></tr>`).join('');
$('queueRows').querySelectorAll('tr').forEach(tr=>tr.onclick=()=>{$('well').value=tr.dataset.well;$('wdate').value=$('week').value;showTab('investigator');investigator()});
Plotly.react('scatterChart',[{type:'scatter',mode:'markers',x:sorted.map(r=>r.oil_daily_avg_2w),y:sorted.map(r=>r.relative_risk_score),text:sorted.map(r=>r.uwi),marker:{size:10,color:sorted.map(r=>r.down_fraction_2w),colorscale:'Viridis',showscale:true,colorbar:{title:'Down frac',thickness:12}}}],{...theme,height:350,xaxis:{title:'Simulated oil rate (m³/day)',gridcolor:'#2b4257'},yaxis:{title:'Simulated score',gridcolor:'#2b4257',tickformat:'.2f'}},plotCfg)
$('week').onchange=queue;$('capacity').onchange=queue;$('cooldown').onchange=queue;$('hindsight').onchange=queue;
$('download').onclick=()=>{const fields=['uwi','relative_risk_score','oil_daily_avg_2w','down_fraction_2w'];const lines=[fields.join(','),...scheduleDemo()[$('week').value].map(r=>fields.map(f=>r[f]).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines],{type:'text/csv'}));a.download='SYNTHETIC_wellguard_queue.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};}
function investigator(){const name=$('well').value,dt=$('wdate').value,h=DEMO.filter(r=>r.uwi===name).sort((a,b)=>a.week_end.localeCompare(b.week_end)),curr=h.filter(x=>x.week_end<=dt),r=curr.find(x=>x.week_end===dt)||curr[curr.length-1],rank=DEMO.filter(x=>x.week_end===dt).sort((a,b)=>b.relative_risk_score-a.relative_risk_score).findIndex(x=>x.uwi===name)+1;lineChart('riskChart',curr.map(x=>x.week_end),curr.map(x=>x.relative_risk_score),'#25d6c8','Relative score');lineChart('oilChart',curr.map(x=>x.week_end),curr.map(x=>x.oil_daily_avg_2w),'#ffc06d','m³/day');$('investigatorText').innerHTML=`<strong>${name}</strong> • historical example snapshot ${dt} • ranking ${rank} / ${WELLS.length}<br><br><strong>Observed (synthetic):</strong> relative score <b>${r.relative_risk_score.toFixed(3)}</b>; daily oil rate <b>${r.oil_daily_avg_2w.toFixed(1)} m³/day</b>; downtime fraction <b>${r.down_fraction_2w.toFixed(2)}</b>; pump RPM <b>${r.rpm_avg_2w.toFixed(1)}</b>.<br><br><strong>Example model drivers:</strong> ${[r.driver_1,r.driver_2,r.driver_3].map(x=>x.replaceAll('_',' ')).join(', ')}. Contributions are associations with the score, <em>not diagnosed mechanical causes</em>.<br><br><strong>Recommended verification:</strong> check live telemetry, maintenance logs, reported downtime codes, and instrument quality with authorized personnel before considering inspection.<br><br><span class="yellow">This is a simulated explanation, not operational advice for a real well.</span>`}
$('well').onchange=investigator;$('wdate').onchange=investigator;
function simulator(){const c=Number($('inspect').value),e=Number($('events').value),o=Number($('oil').value),a=Number($('address').value)/100,s=Number($('success').value)/100,v=Number($('value').value),cost=Number($('cost').value);for(const [k,x] of Object.entries({vInspect:c,vEvents:e,vOil:o,vAddr:100*a+'%',vSuccess:100*s+'%',vValue:money(v),vCost:money(cost)}))$(k).textContent=x;const avoided=e*o*a*s;const gross=avoided*v;const spend=c*cost;$('simOil').textContent=avoided.toFixed(1);$('simGross').textContent=money(gross);$('simSpend').textContent=money(spend);$('simNet').textContent=money(gross-spend);const denom=e*o*a*v;const breakeven=denom>0?spend/denom:Infinity;$('breakEvenReport').textContent=isFinite(breakeven)?('Hypothetical break-even intervention success: '+(breakeven*100).toFixed(1)+'%'+(breakeven>1?' — above 100%; scenario not viable under assumptions.':'')):'Break-even undefined: assumed gross benefit per successful intervention is zero.';const sr=Array.from({length:21},(_,i)=>i*5);Plotly.react('sensitivityChart',[{type:'scatter',mode:'lines+markers',x:sr,y:sr.map(x=>e*o*a*(x/100)*v-spend),line:{color:'#25cfc2',width:3}}],{...theme,height:305,xaxis:{title:'Assumed successful intervention rate (%)',gridcolor:'#2b4257'},yaxis:{title:'Hypothetical net CAD / week',gridcolor:'#2b4257'},shapes:[{type:'line',x0:0,x1:100,y0:0,y1:0,line:{color:'#ffbd64',dash:'dash'}}]},plotCfg)}
['inspect','events','oil','address','success','value','cost'].forEach(id=>$(id).oninput=simulator);
overview();queue();investigator();simulator();</script></body></html>'''
html=html.replace('__PLOTLY_SOURCE__',get_plotlyjs()).replace('__DEMO_DATA__',json.dumps(rows,separators=(',',':')))
html=html.replace('__CATEGORY_DATA__',json.dumps([['Long-term shut-in',162412],['Downhole equipment – rods',72080],['Rodstring failure',40015],['Facility capacity',29374],['Downhole equipment – pump',24205],['Tubing failure',24097]]))
html=html.replace('__METRIC_DATA__',json.dumps({'ap':.164}))
out=ROOT/'demo'/'WellGuard_AI_Interactive_Offline_Demo.html';out.write_text(html,encoding='utf-8')
print(out,round(out.stat().st_size/1e6,2),'MB')
